-- One-time initialization. Runtime uses only integration_settings.settings.actorAdapters.
-- Existing custom adapters are preserved; seed only when the selected Actor matches.
WITH seed AS (SELECT '{"tiktok_posts":{"actorId":"clockworks/tiktok-scraper","inputTemplate":{"searchQueries":"{{queries}}","searchSection":"/video","resultsPerPage":"{{perQueryLimit}}","videoSearchSorting":"LATEST","videoSearchDateFilter":"PAST_WEEK","commentsPerPost":0,"scrapeRelatedVideos":false,"shouldDownloadVideos":false,"aiVideoDescription":false,"aiVideoSummary":false},"output":{"id":["id"],"text":["text"],"url":["webVideoUrl"],"publishedAt":["createTimeISO","createTime"],"authorHandle":["authorMeta.name","author.uniqueId"],"authorName":["authorMeta.nickName","author.nickname"]}},"instagram_posts":{"actorId":"apify/instagram-scraper","inputTemplate":{"search":"#{{hashtag}}","searchType":"hashtag","resultsType":"posts","resultsLimit":"{{limit}}","searchLimit":1,"onlyPostsNewerThan":"{{since}}"},"output":{"id":["shortCode","shortcode"],"text":["caption"],"url":["url"],"publishedAt":["timestamp"],"authorHandle":["ownerUsername"],"authorName":["ownerFullName"]}},"tiktok_comments":{"actorId":"clockworks/tiktok-comments-scraper","inputTemplate":{"postURLs":"{{parentUrls}}","commentsPerPost":"{{commentsPerPost}}","maxRepliesPerComment":0},"output":{"id":["cid","id","commentId"],"text":["text"],"publishedAt":["createTimeISO","createTime"],"parentUrl":["videoWebUrl","videoUrl","postUrl"],"parentId":["videoId"],"authorHandle":["uniqueId","author.uniqueId"],"authorName":["nickname","author.nickname"]}},"instagram_comments":{"actorId":"apidojo/instagram-comments-scraper-api","inputTemplate":{"startUrls":"{{parentUrls}}","maxItems":"{{maxComments}}","fetchReplies":false,"continueOnDuplicates":false},"output":{"id":["id","commentId"],"text":["message","text"],"publishedAt":["createdAt","timestamp"],"parentUrl":["inputSource","postUrl"],"parentId":["postId"],"authorHandle":["user.username","ownerUsername"],"authorName":["user.fullName","ownerFullName"]}},"tiktok_hashtag":{"actorId":"clockworks/tiktok-hashtag-scraper","inputTemplate":{"hashtags":"{{hashtags}}","resultsPerPage":"{{limit}}","shouldDownloadVideos":false,"oldestPostDateUnified":"{{since}}","newestPostDate":"{{untilInclusive}}"},"output":{"id":["id"],"text":["text"],"url":["webVideoUrl"],"publishedAt":["createTimeISO","createTime"],"authorHandle":["authorMeta.name","author.uniqueId"],"authorName":["authorMeta.nickName","author.nickname"]}},"instagram_hashtag":{"actorId":"apify/instagram-hashtag-scraper","inputTemplate":{"hashtags":"{{hashtags}}","resultsType":"posts","resultsLimit":"{{limit}}","onlyPostsNewerThan":"{{since}}"},"output":{"id":["shortCode","shortcode"],"text":["caption"],"url":["url"],"publishedAt":["timestamp"],"authorHandle":["ownerUsername"],"authorName":["ownerFullName"]}}}'::jsonb AS adapters), fields(kind,field) AS (VALUES ('tiktok_posts','tiktokActor'),
('instagram_posts','instagramActor'),
('tiktok_comments','tiktokCommentsActor'),
('instagram_comments','instagramCommentsActor'),
('tiktok_hashtag','tiktokHashtagActor'),
('instagram_hashtag','instagramHashtagActor')),
 eligible AS (
 SELECT s.organization_id,s.provider_id,jsonb_object_agg(f.kind,seed.adapters->f.kind) AS adapters
 FROM integration_settings s JOIN integration_providers p ON p.id=s.provider_id AND p.code='apify'
 JOIN organizations o ON o.id=s.organization_id AND o.active=true CROSS JOIN seed CROSS JOIN fields f
 WHERE replace(s.settings->>f.field,'~','/')=seed.adapters->f.kind->>'actorId'
 GROUP BY s.organization_id,s.provider_id
 )
 UPDATE integration_settings s SET settings=jsonb_set(s.settings,'{actorAdapters}',e.adapters||COALESCE(s.settings->'actorAdapters','{}'::jsonb)),updated_at=now()
 FROM eligible e WHERE s.organization_id=e.organization_id AND s.provider_id=e.provider_id
 RETURNING s.organization_id, s.settings->'actorAdapters' AS actor_adapters;
